<template><section class="space-y-6"><header><p class="text-xs font-black tracking-widest text-indigo-600">MANAGEMENT</p><h1 class="mt-2 text-3xl font-black">Catalog & inventory</h1><p class="text-slate-500">Manage company products, variants, stock, suppliers and purchasing.</p></header><nav class="flex flex-wrap gap-2"><button v-for="t in tabs" :key="t" @click="tab=t" :class="['rounded-xl px-4 py-2 text-sm font-bold',tab===t?'bg-slate-950 text-white':'border bg-white']">{{t}}</button></nav><div v-if="tab==='Products'" class="space-y-5"><div class="rounded-2xl border bg-white p-6"><div class="grid gap-3 md:grid-cols-3"><input v-model="form.name" class="rounded-xl border p-3" placeholder="Product name"><select v-model="form.categoryId" @change="loadRules" class="rounded-xl border p-3"><option value="">Category</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="form.brandId" class="rounded-xl border p-3"><option value="">Brand</option><option v-for="b in brands" :key="b.id" :value="b.id">{{b.name}}</option></select><input v-model="form.sku" class="rounded-xl border p-3" placeholder="Base SKU"><input v-model.number="form.price" type="number" class="rounded-xl border p-3" placeholder="Price"><input v-model="form.imageUrl" class="rounded-xl border p-3" placeholder="Image URL"></div><textarea v-model="form.description" class="mt-3 w-full rounded-xl border p-3" placeholder="Description"></textarea></div><div v-if="rules.length" class="rounded-2xl border bg-white p-6"><h2 class="font-black">Category attributes</h2><div v-for="r in rules" :key="r.attribute.id" class="mt-4 rounded-xl border p-4"><div class="flex justify-between"><b>{{r.attribute.name}}</b><span class="text-xs text-slate-500">{{r.isVariant?'Variant option':'Product detail'}} · {{r.isRequired?'Required':'Optional'}}</span></div><div class="mt-3 flex flex-wrap gap-2"><button v-for="v in r.attribute.values" :key="v.id" @click="toggle(r,v.id)" :class="['rounded-lg border px-3 py-2 text-sm font-bold',selected[r.attribute.id]?.includes(v.id)?'border-indigo-600 bg-indigo-50':'']">{{v.label||v.value}}</button></div></div></div><div v-if="variantRules.length" class="rounded-2xl border bg-white p-6"><div class="flex justify-between"><div><h2 class="font-black">Variant combinations</h2><p class="text-sm text-slate-500">Choose values, then generate every sellable SKU.</p></div><button @click="generate" class="rounded-xl bg-indigo-600 px-4 py-2 font-bold text-white">Generate</button></div><div v-if="variants.length" class="mt-4 space-y-3"><div v-for="(v,i) in variants" :key="i" class="grid gap-3 rounded-xl bg-slate-50 p-4 md:grid-cols-5"><div class="font-bold md:col-span-2">{{v.label}}</div><input v-model="v.sku" class="rounded-lg border p-2" placeholder="SKU"><input v-model.number="v.price" type="number" class="rounded-lg border p-2" placeholder="Price"><select v-model="v.warehouseId" class="rounded-lg border p-2"><option value="">Warehouse</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select><input v-model.number="v.quantity" type="number" min="0" class="rounded-lg border p-2" placeholder="Opening stock"></div></div></div><button @click="saveProduct" :disabled="busy" class="rounded-xl bg-slate-950 px-6 py-3 font-bold text-white">{{busy?'Saving…':'Create product'}}</button><p v-if="message" class="text-sm">{{message}}</p></div><div v-else-if="tab==='Inventory'" class="grid gap-5 lg:grid-cols-2"><div class="rounded-2xl border bg-white p-6"><h2 class="font-black">Inventory adjustment</h2><div class="mt-4 space-y-3"><select v-model="adjust.warehouseId" class="w-full rounded-xl border p-3"><option value="">Warehouse</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select><select v-model="adjust.variantId" class="w-full rounded-xl border p-3"><option value="">Variant</option><option v-for="v in variantsAll" :key="v.id" :value="v.id">{{v.product?.name}} · {{v.sku}}</option></select><select v-model="adjust.type" class="w-full rounded-xl border p-3"><option value="receive">Receive</option><option value="adjustment_in">Adjustment in</option><option value="adjustment_out">Adjustment out</option><option value="damage">Damage</option><option value="return">Return</option></select><input v-model.number="adjust.quantity" type="number" min="1" class="w-full rounded-xl border p-3" placeholder="Quantity"><input v-model="adjust.note" class="w-full rounded-xl border p-3" placeholder="Reason"><button @click="moveStock" class="w-full rounded-xl bg-slate-950 p-3 font-bold text-white">Record movement</button></div></div><div class="rounded-2xl border bg-white p-6"><h2 class="font-black">Warehouse stock</h2><div class="mt-4 space-y-2"><div v-for="x in inventory" :key="x.id" class="flex justify-between rounded-xl bg-slate-50 p-3"><div><b>{{x.variant?.product?.name}}</b><p class="text-xs text-slate-500">{{x.variant?.sku}} · {{x.warehouse?.name}}</p></div><b>{{x.quantityOnHand}} <span class="text-xs text-slate-500">available</span></b></div></div></div></div><div v-else-if="tab==='Attributes'" class="grid gap-5 lg:grid-cols-2"><div class="rounded-2xl border bg-white p-6"><h2 class="font-black">Attribute library</h2><div class="mt-3 grid gap-3"><input v-model="af.name" class="rounded-xl border p-3" placeholder="Color, Size, Material..."><select v-model="af.type" class="rounded-xl border p-3"><option value="select">Select</option><option value="color">Color</option><option value="text">Text</option><option value="number">Number</option><option value="boolean">Boolean</option></select><input v-model="af.values" class="rounded-xl border p-3" placeholder="Black, White, Red"><button @click="createAttribute" class="rounded-xl bg-slate-950 p-3 font-bold text-white">Create attribute</button></div><div class="mt-5 space-y-2"><div v-for="a in attributes" :key="a.id" class="rounded-xl bg-slate-50 p-3"><b>{{a.name}}</b><p class="text-xs text-slate-500">{{a.type}} · {{a.values?.length||0}} values</p></div></div></div><div class="rounded-2xl border bg-white p-6"><h2 class="font-black">Category rules</h2><select v-model="assign.categoryId" class="mt-3 w-full rounded-xl border p-3"><option value="">Category</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="assign.attributeId" class="mt-3 w-full rounded-xl border p-3"><option value="">Attribute</option><option v-for="a in attributes" :key="a.id" :value="a.id">{{a.name}}</option></select><label class="mt-3 block"><input type="checkbox" v-model="assign.isRequired"> Required</label><label class="mt-2 block"><input type="checkbox" v-model="assign.isVariant"> Used to generate variants</label><button @click="assignAttribute" class="mt-4 w-full rounded-xl bg-indigo-600 p-3 font-bold text-white">Save category rule</button></div></div><div v-else-if="tab==='Warehouses'||tab==='Suppliers'||tab==='Brands'" class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">{{tab}}</h2><div v-if="tab==='Warehouses'" class="mt-4 grid gap-3 md:grid-cols-3"><input v-model="wf.code" class="rounded-xl border p-3" placeholder="Code"><input v-model="wf.name" class="rounded-xl border p-3" placeholder="Name"><input v-model="wf.city" class="rounded-xl border p-3" placeholder="City"><button @click="createWarehouse" class="rounded-xl bg-slate-950 p-3 font-bold text-white">Add warehouse</button></div><div v-if="tab==='Suppliers'" class="mt-4 grid gap-3 md:grid-cols-2"><input v-model="sf.name" class="rounded-xl border p-3" placeholder="Supplier"><input v-model="sf.contactName" class="rounded-xl border p-3" placeholder="Contact"><input v-model="sf.phone" class="rounded-xl border p-3" placeholder="Phone"><input v-model="sf.email" class="rounded-xl border p-3" placeholder="Email"><button @click="createSupplier" class="rounded-xl bg-slate-950 p-3 font-bold text-white">Add supplier</button></div><div v-if="tab==='Brands'" class="mt-4 flex gap-3"><input v-model="brandName" class="flex-1 rounded-xl border p-3" placeholder="Brand name"><button @click="createBrand" class="rounded-xl bg-slate-950 px-5 font-bold text-white">Add brand</button></div><div class="mt-5 grid gap-3 md:grid-cols-3"><div v-for="x in currentItems" :key="x.id" class="rounded-xl bg-slate-50 p-4"><b>{{x.name}}</b><p class="text-xs text-slate-500">{{x.code||x.contactName||x.slug||''}}</p></div></div></div></section></template>
<script>import api from'../services/api';export default{data(){return{tab:'Products',tabs:['Products','Attributes','Inventory','Brands','Warehouses','Suppliers'],categories:[],brands:[],warehouses:[],suppliers:[],attributes:[],rules:[],inventory:[],variantsAll:[],selected:{},variants:[],busy:false,message:'',brandName:'',af:{name:'',type:'select',values:''},assign:{categoryId:'',attributeId:'',isRequired:false,isVariant:false},wf:{code:'',name:'',city:''},sf:{name:'',contactName:'',phone:'',email:''},adjust:{warehouseId:'',variantId:'',type:'receive',quantity:1,note:''},form:{name:'',categoryId:'',brandId:'',sku:'',price:0,imageUrl:'',description:'',status:'active'}}},computed:{variantRules(){return this.rules.filter(x=>x.isVariant)},currentItems(){return this.tab==='Warehouses'?this.warehouses:this.tab==='Suppliers'?this.suppliers:this.brands}},async mounted(){await this.load()},methods:{async load(){const [c,b,w,s,a,i,p]=await Promise.all([api.get('/categories'),api.get('/brands'),api.get('/warehouses'),api.get('/suppliers'),api.get('/attributes'),api.get('/inventory'),api.get('/products',{params:{limit:100}})]);this.categories=c.data.data||[];this.brands=b.data.data||[];this.warehouses=w.data.data||[];this.suppliers=s.data.data||[];this.attributes=a.data.data||[];this.inventory=i.data.data||[];this.variantsAll=(p.data.data||[]).flatMap(x=>(x.variants||[]).map(v=>({...v,product:x})))},async loadRules(){this.rules=(await api.get('/attributes/categories/'+this.form.categoryId)).data.data||[];this.selected={};this.variants=[]},toggle(r,id){const x=this.selected[r.attribute.id]||[];this.selected[r.attribute.id]=x.includes(id)?x.filter(v=>v!==id):[...x,id]},generate(){let c=[[]];for(const r of this.variantRules){const vals=(r.attribute.values||[]).filter(v=>(this.selected[r.attribute.id]||[]).includes(v.id));c=c.flatMap(a=>vals.map(v=>[...a,{r,v}]))}this.variants=c.map((a,i)=>({label:a.map(x=>x.v.label||x.v.value).join(' / '),sku:(this.form.sku||'SKU')+'-'+String(i+1).padStart(3,'0'),price:Number(this.form.price),warehouseId:this.warehouses[0]?.id||'',quantity:0,options:a.map(x=>({attributeId:x.r.attribute.id,attributeValueId:x.v.id}))}))},async saveProduct(){this.busy=true;this.message='';try{const attributeValues=[];for(const r of this.rules)for(const id of(this.selected[r.attribute.id]||[]))attributeValues.push({attributeId:r.attribute.id,attributeValueId:id});const vs=this.variants.length?this.variants:[{sku:this.form.sku||'SKU-'+Date.now(),price:this.form.price,options:[],inventory:this.warehouses[0]?[{warehouseId:this.warehouses[0].id,quantity:0}]:[]}];vs.forEach(v=>v.inventory=v.warehouseId?[{warehouseId:v.warehouseId,quantity:Number(v.quantity||0)}]:[]);await api.post('/products',{...this.form,attributeValues,variants:vs});this.message='Product created.';this.form={name:'',categoryId:'',brandId:'',sku:'',price:0,imageUrl:'',description:'',status:'active'};this.rules=[];this.selected={};this.variants=[];await this.load()}catch(e){this.message=e.response?.data?.message||'Could not create product'}finally{this.busy=false}},async createAttribute(){await api.post('/attributes',{name:this.af.name,type:this.af.type,values:this.af.values.split(',').map(v=>({value:v.trim(),label:v.trim()})).filter(v=>v.value)});this.af={name:'',type:'select',values:''};await this.load()},async assignAttribute(){await api.post('/attributes/categories/'+this.assign.categoryId,this.assign);this.assign={categoryId:'',attributeId:'',isRequired:false,isVariant:false};await this.load()},async createWarehouse(){await api.post('/warehouses',this.wf);this.wf={code:'',name:'',city:''};await this.load()},async createSupplier(){await api.post('/suppliers',this.sf);this.sf={name:'',contactName:'',phone:'',email:''};await this.load()},async createBrand(){await api.post('/brands',{name:this.brandName});this.brandName='';await this.load()},async moveStock(){await api.post('/inventory/adjust',this.adjust);this.adjust={...this.adjust,quantity:1,note:''};await this.load()}}}</script>